/* =====================================================
   ⚙️  LÓGICA
   ===================================================== */
const $ = id => document.getElementById(id);
const canvas = $("cielo"), ctx = canvas.getContext("2d");
let w, h, fondo = [], fugaces = [], t = 0;

const FORMA = [[-.6, .6], [-.6, -.05], [0, -.6], [.6, -.05], [.6, .6]];
const ARISTAS = [[0, 1], [1, 2], [2, 3], [3, 4], [4, 0]].map(([a, b]) => ({ a, b, p: 0 }));
let estrellas = [];
const visitadas = new Set();

function ajustar() {
  const dpr = window.devicePixelRatio || 1;
  w = innerWidth; h = innerHeight;
  canvas.width = w * dpr; canvas.height = h * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  fondo = Array.from({ length: Math.floor(w * h / 4500) }, () => ({
    x: Math.random() * w, y: Math.random() * h, r: Math.random() * 1.3 + .2,
    a: Math.random() * .6 + .3, v: Math.random() * 1.5 + .5, f: Math.random() * 6.28,
  }));

  const esMovil = w < 600;
  const mitad = Math.min(w * (esMovil ? 0.65 : 0.75), h * 0.45) / 2;
  const cx = w / 2;
  const cy = h * (esMovil ? 0.48 : 0.42);

  estrellas = FORMA.map(([px, py]) => ({ x: cx + px * mitad, y: cy + py * mitad }));
}
addEventListener("resize", ajustar); 
ajustar();

function lanzarFugaz() {
  if (typeof w === "undefined" || typeof h === "undefined" || !Array.isArray(fugaces)) return;
  const x = w * (0.4 + Math.random() * 0.6);
  const y = Math.random() * h * 0.3;
  
  fugaces.push({
    x: x,
    y: y,
    vx: -3 - Math.random() * 1.5,
    vy: 1.5 + Math.random() * 1,
    vida: 1
  });
  
  setTimeout(lanzarFugaz, 6000 + Math.random() * 6000);
}

function dibujar() {
  t += .016;
  ctx.clearRect(0, 0, w, h);

  // Estrellas de fondo
  for (const s of fondo) {
    const alfa = s.a * (0.5 + 0.5 * Math.sin(t * s.v + s.f));
    ctx.fillStyle = `rgba(255, 255, 255, ${alfa})`;
    ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, 6.28); ctx.fill();
  }

  // Líneas
  ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(255,227,163,.9)";
  ctx.shadowColor = "#ffe3a3"; ctx.shadowBlur = 12;
  for (const e of ARISTAS) {
    if (visitadas.has(e.a) && visitadas.has(e.b)) e.p = Math.min(1, e.p + .03);
    if (e.p <= 0) continue;
    const A = estrellas[e.a], B = estrellas[e.b];
    ctx.beginPath(); ctx.moveTo(A.x, A.y);
    ctx.lineTo(A.x + (B.x - A.x) * e.p, A.y + (B.y - A.y) * e.p); ctx.stroke();
  }

  // Estrellas principales
  estrellas.forEach((s, i) => {
    const on = visitadas.has(i), pulso = 1 + .15 * Math.sin(t * 2 + i);
    const r = (on ? 9 : 7) * pulso;
    const g = ctx.createRadialGradient(s.x, s.y, 0, s.x, s.y, r * 4);
    g.addColorStop(0, on ? "rgba(255,240,200,1)" : "rgba(255,255,255,.95)");
    g.addColorStop(.25, on ? "rgba(255,227,163,.6)" : "rgba(200,180,255,.4)");
    g.addColorStop(1, "rgba(255,227,163,0)");
    ctx.shadowBlur = 0; ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(s.x, s.y, r * 4, 0, 6.28); ctx.fill();
  });

  // Estrellas fugaces
  ctx.shadowBlur = 0;
  for (const f of fugaces) {
    f.x += f.vx; 
    f.y += f.vy; 
    f.vida -= .004;

    const alfa = Math.max(0, f.vida);
    if (alfa <= 0) continue;

    const g = ctx.createLinearGradient(f.x, f.y, f.x - f.vx * 8, f.y - f.vy * 8);
    g.addColorStop(0, `rgba(255, 255, 255, ${alfa})`);
    g.addColorStop(1, "rgba(255, 255, 255, 0)");

    ctx.strokeStyle = g; 
    ctx.lineWidth = 2;
    ctx.beginPath(); 
    ctx.moveTo(f.x, f.y); 
    ctx.lineTo(f.x - f.vx * 8, f.y - f.vy * 8); 
    ctx.stroke();
  }
  fugaces = fugaces.filter(f => f.vida > 0);

  requestAnimationFrame(dibujar);
}
dibujar();

function mostrarPanel(titulo, texto, foto) {
  $("panelTitulo").textContent = titulo;
  $("panelTexto").textContent = texto;
  const img = $("panelFoto"); img.style.display = "none";
  if (foto) { img.onload = () => img.style.display = "block"; img.src = foto; }
  $("panel").classList.remove("oculto");
  $("panel").scrollTop = 0;
}
$("cerrarPanel").onclick = () => $("panel").classList.add("oculto");

const manejarToque = ev => {
  const rect = canvas.getBoundingClientRect();
  const x = ev.clientX - rect.left;
  const y = ev.clientY - rect.top;
  const radioToque = window.innerWidth < 600 ? 45 : 35;

  const f = fugaces.find(f => Math.hypot(f.x - x, f.y - y) < 60);
  if (f) {
    f.vida = 0;
    mostrarPanel("Una estrella fugaz ✨", NOTAS_FUGACES[Math.floor(Math.random() * NOTAS_FUGACES.length)]);
    return;
  }

  const i = estrellas.findIndex(s => Math.hypot(s.x - x, s.y - y) < radioToque);
  if (i < 0) return;

  visitadas.add(i);
  $("contador").textContent = `${visitadas.size} / 5`;
  mostrarPanel(RECUERDOS[i].titulo, RECUERDOS[i].texto, RECUERDOS[i].foto);

  if (visitadas.size === 5) {
    $("pista").textContent = "Tu casa en el cielo está completa";
    $("btnFinal").classList.remove("oculto");
  }
};

canvas.addEventListener("pointerdown", manejarToque);

const musica = $("musica");
$("btnIniciar").onclick = () => {
  $("inicio").classList.add("fuera");
  $("hud").classList.remove("oculto"); 
  $("btnMusica").classList.remove("oculto");
  musica.volume = .6; 
  musica.play().catch(() => {});
  setTimeout(lanzarFugaz, 3000);
};

$("btnMusica").onclick = e => {
  musica.paused ? musica.play() : musica.pause();
  e.currentTarget.classList.toggle("silencio", musica.paused);
};

$("btnFinal").onclick = () => {
  $("cartaTexto").replaceChildren(...CARTA.map(txt => Object.assign(document.createElement("p"), { textContent: txt })));
  $("carta").classList.remove("oculto");
  const hoja = document.querySelector(".hoja");
  if (hoja) hoja.scrollTop = 0;
};

$("cerrarCarta").onclick = () => $("carta").classList.add("oculto");